use serde_json::json;
use sha2::{Digest,Sha256};
use std::{fs,path::Path};
fn main(){let root=Path::new("/tmp/zopro-serial-fft-leaves");let source=fs::read_to_string(root.join("candidate-v2/crates/zopro-core/src/fft/pair.rs")).unwrap();let base=fs::read_to_string("/home/ubuntu/src/zk-tools/zopro/crates/zopro-core/src/fft/pair.rs").unwrap();let entry="    #[cfg(zopro_serial_fft_leaves)]\n    if serial_leaf::enabled() { return serial_leaf::transform::<S, FORWARD>(values, roots, level); }\n";let recovered=source.replace(entry,"").replace("\n#[cfg(any(zopro_serial_fft_leaves, test))]\nmod serial_leaf;\n","");assert_eq!(recovered,base);let start=base.find("fn stored_transform<S:").unwrap();let end=base[start..].find("\n// Keep the fixed column scratch").unwrap()+start;let module=fs::read_to_string(root.join("candidate-v2/crates/zopro-core/src/fft/pair/serial_leaf.rs")).unwrap();let old=fs::read_to_string(root.join("candidate/crates/zopro-core/src/fft/pair/serial_leaf.rs")).unwrap();assert_eq!(old.split("#[cfg(test)]").next(),module.split("#[cfg(test)]").next());let a=module.find("fn transform_inner<S:").unwrap();let b=module[a..].find("\n// These binary boundaries").unwrap()+a;let restored=module[a..b].replacen("fn transform_inner<","fn stored_transform<",1).replace("    cutoff: usize,\n","").replace("dit_bounded(&mut local, roots, level, cutoff);","dit::<5>(&mut local, roots, level);").replace("dif_bounded(&mut local, roots, level, cutoff);","dif::<5>(&mut local, roots, level);").replace("transform_inner::<S, FORWARD>(part, roots, level + 5, cutoff)","stored_transform::<S, FORWARD>(part, roots, level + 5)");assert_eq!(restored.trim(),base[start..end].trim());let terminal=module.split("// Retain the existing sequential butterfly kernels").nth(1).unwrap().split("#[cfg(test)]").next().unwrap();for forbidden in ["rayon::","Vec<","collect(","::new(","reserve("]{assert!(!terminal.contains(forbidden),"terminal contains {forbidden}");}for kernel in ["dif_quads(","dit_quads(","dif_within(","dit_within("]{assert_eq!(terminal.matches(kernel).count(),1);}
let result=json!({"status":"source structure audit passed","base_pair_sha256":format!("{:x}",Sha256::digest(base.as_bytes())),"original_off_body_recovered":true,"packed32way_geometry_and_expanded_vector_load_store_drop_recovered":true,"runtime_prefix_identical_before_and_after_test_fixture_repair":true,"terminal_functions_have_no_forks_or_heap_allocation":true,"terminal_arithmetic":"Calls existing DIF/DIT quad and within-pair kernels; scalar-polynomial and SDK verification still required.","limits":"Source structure is not a fairness proof, maximum processRAM measurement, portable/concurrent SDK qualification or speed result."});fs::write(root.join("source-audit.json"),format!("{}\n",serde_json::to_string_pretty(&result).unwrap())).unwrap();println!("SOURCE_STRUCTURE_VERIFIED");}
